contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmount, uint minSumVal) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        c.SetMinSum(minSumVal); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint bal0 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint bal1 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cbalBefore = address(c).balance;
        uint beforeSelf = address(this).balance;
        c.Collect(depositAmount); if (__ESBMC_reverted()) return;
        uint bal2 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cbalAfter = address(c).balance;
        uint afterSelf = address(this).balance;
        assert(bal1 == bal0 + depositAmount || bal2 == bal1 - depositAmount || cbalBefore == cbalAfter);
    }
    receive() external payable {}
}

