pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depositAmount, uint256 minSumVal) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.SetMinSum(minSumVal) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 bal0;
        try c.balances(address(this)) returns (uint256 __r) { bal0 = __r; } catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 bal1;
        try c.balances(address(this)) returns (uint256 __r) { bal1 = __r; } catch { return; }
        uint cbalBefore = address(c).balance;
        uint beforeSelf = address(this).balance;
        try c.Collect(depositAmount) {} catch { return; }
        uint256 bal2;
        try c.balances(address(this)) returns (uint256 __r) { bal2 = __r; } catch { return; }
        uint cbalAfter = address(c).balance;
        uint afterSelf = address(this).balance;
        assertTrue(bal1 == bal0 + depositAmount || bal2 == bal1 - depositAmount || cbalBefore == cbalAfter);
    }

    function testFuzz_run(uint256 depositAmount, uint256 minSumVal) public {
        _run(depositAmount, minSumVal);
    }

    receive() external payable {}
}
